definition.css:
/* Comparison table - cell text */
.table td, .table th {
  font-size: 14px !important;
}

/* Filter panel labels */
.ant-select-selection-item,
.filter-title,
[data-test="filter-title"] {
  font-size: 14px !important;
}

/* Text boxes / markdown components */
.dashboard-component-chart-holder p,
.dashboard-component-chart-holder li {
  font-size: 15px !important;
}

/* Chart titles */
.header-title {
  font-size: 15px !important;
}

/* Chart/table container header title */
.header-title {
  font-size: 16px !important;
}

/* Table cell text stays at 14px */
.table td, .table th {
  font-size: 14px !important;
}
/* The anchor follows the title text; allow room for two title lines below the fixed toolbar. */
[id^="HEADER-"] { scroll-margin-top: 140px; }
